//import './App.css';
import 'bootstrap/dist/css/bootstrap.min.css';
import { Button } from 'reactstrap';
import { Component } from 'react';

class App extends Component {
  constructor(props) {
    super(props)
    this.state = {
      color1: "primary",
      color2: "secondary",
      color3: "warning",
    }
  }

  cambiarColor1() {
    this.setState({ color1: 'success' });
  }

  cambiarColor2() {
    this.setState({ color2: 'danger' });
  }

  cambiarColor3() {
    this.setState({ color3: 'info' });
  }

  render() {
    return (
      <div className="App">
        <Button  onClick={this.cambiarColor1}></Button>
        <Button color={this.state.color2} onClick={this.cambiarColor1}></Button>
        <Button color={this.state.color3} onClick={this.cambiarColor1}></Button>
      </div>
    );
  }
}

export default App;
